    'faq_note' => 'Answers to common questions.',
    'faq_q1' => '<strong>What is TropaTT?</strong><br>A free खोलें-source self-hosted CRM, कार्य manager, और प्रोजेक्ट management platform.',
    'faq_q10' => 'Who is developer?',
    'faq_q10_answer' => '<strong>Anton Barinov</strong>, a PHP developer.',
    'faq_q2' => '<strong>Is it a CRM or a कार्य manager?</strong><br>Both. A CRM for क्लाइंट और counterparties, a कार्य manager for कार्य, plus प्रोजेक्ट management, chat, कैलेंडर, और AI.',
    'faq_q3' => '<strong>Is it suitable for freelancers?</strong><br>Yes. There is no minimum टीम size. A single उपयोगकर्ता gets CRM, कार्य, an AI day plan, और chat without per-seat fees.',
    'faq_q4' => '<strong>Does it work on shared hosting?</strong><br>Yes. PHP 8.1+ और MySQL are enough. browser installer configures everything.',
    'faq_q5' => '<strong>Are there limits on users और कार्य?</strong><br>No. Unlimited users, कार्य, projects, और क्लाइंट. only limitation is server capacity.',
    'faq_q6' => '<strong>Where is डेटा stored?</strong><br>100% on your server. system never syncs डेटा to cloud.',
    'faq_q7' => '<strong>What AI tools are उपलब्ध?</strong><br>20+ tools: idea exploration, day/सप्ताह plans, summaries, checklists, risks, meeting preparation.',
